import assert from 'node:assert/strict';import {run,Budget} from '@poe-platform/safe-js';
await assert.rejects(run('/a\r\n/',{budget:new Budget({stringLength:2})}),{name:'SandboxError',code:'budgetExceeded',budget:'stringLength',current:3,limit:2});
await run('/a/',{budget:new Budget({stringLength:2})});
console.log(JSON.stringify({status:'passed',node:process.version,icu:process.versions.icu}));
